#!/usr/bin/env python3
"""Slack Web API helper (Python 3, stdlib only).

Common Slack API operations with a bot token. No third-party dependencies.

Usage:
    SLACK_BOT_TOKEN=xoxb-... python3 slack_api.py <command> [options]

Commands:
    test             Verify token via auth.test
    post             Send a message (chat.postMessage)
    reply            Reply inside a thread (chat.postMessage with thread_ts)
    list-channels    List channels (conversations.list, paginated)
    history          Read recent messages (conversations.history)
    users            List workspace users (users.list, paginated)
    upload           Upload a file to a channel (files v2 two-step flow)
    create-channel   Create a public or private channel (conversations.create)

Every subcommand accepts:
    --token TOKEN    Bot token (default: $SLACK_BOT_TOKEN)
    --dry-run        Print the request instead of sending it

Output: concise JSON on stdout. Errors: "Failure: ..." on stderr, exit code 1.
"""

import argparse
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

API_BASE = "https://slack.com/api/"


class SlackError(Exception):
    """A clean, user-facing error (no traceback)."""


def _http_request(url, *, method="GET", body=None, headers=None):
    headers = dict(headers or {})
    data = body.encode("utf-8") if isinstance(body, str) else body
    req = urllib.request.Request(url, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        raise SlackError(
            "HTTP %s: %s" % (e.code, e.read().decode("utf-8", "replace")[:500])
        )


def api(token, method, params=None):
    """Call a Slack API method with form-encoded POST and check ok:true."""
    headers = {
        "Authorization": "Bearer %s" % token,
        "Content-Type": "application/x-www-form-urlencoded",
    }
    payload = _http_request(
        API_BASE + method,
        method="POST",
        body=urllib.parse.urlencode(params or {}),
        headers=headers,
    )
    if not payload.get("ok"):
        raise SlackError(payload.get("error", "unknown_error"))
    return payload


def paginate(token, method, params, items_key):
    """Follow response_metadata.next_cursor until all pages are fetched."""
    items = []
    cursor = None
    while True:
        p = dict(params)
        if cursor:
            p["cursor"] = cursor
        payload = api(token, method, p)
        items.extend(payload.get(items_key) or [])
        meta = payload.get("response_metadata") or {}
        cursor = meta.get("next_cursor") or ""
        if not cursor:
            break
    return items


def resolve_channel(token, channel):
    """Resolve a channel name ('general', '#general') to an encoded ID (C...).

    Encoded IDs (C... followed by at least 8 chars) are returned unchanged.
    """
    if channel.startswith("#"):
        channel = channel[1:]
    if channel.startswith("C") and len(channel) >= 9:
        return channel
    channels = paginate(
        token,
        "conversations.list",
        {"limit": 200, "types": "public_channel,private_channel", "exclude_archived": "true"},
        "channels",
    )
    for conv in channels:
        if conv.get("name") == channel:
            return conv["id"]
    raise SlackError("channel_not_found: no channel named '%s'" % channel)


def _emit(obj):
    print(json.dumps(obj, ensure_ascii=False))


def _dry(method, params):
    _emit({"dry_run": True, "method": method, "params": params})


# --- Command handlers -------------------------------------------------------


def cmd_test(args):
    if args.dry_run:
        return _dry("auth.test", {})
    payload = api(args.token, "auth.test")
    _emit(
        {
            "ok": True,
            "bot_id": payload.get("bot_id"),
            "user": payload.get("user"),
            "team": payload.get("team"),
            "url": payload.get("url"),
        }
    )


def cmd_post(args):
    params = {"channel": args.channel, "text": args.text}
    if args.thread_ts:
        params["thread_ts"] = args.thread_ts
    if args.dry_run:
        return _dry("chat.postMessage", params)
    payload = api(args.token, "chat.postMessage", params)
    _emit({"ok": True, "channel": payload.get("channel"), "ts": payload.get("ts")})


def cmd_reply(args):
    params = {
        "channel": args.channel,
        "text": args.text,
        "thread_ts": args.thread_ts,
    }
    if args.dry_run:
        return _dry("chat.postMessage", params)
    payload = api(args.token, "chat.postMessage", params)
    _emit(
        {
            "ok": True,
            "channel": payload.get("channel"),
            "ts": payload.get("ts"),
            "thread_ts": payload.get("thread_ts"),
        }
    )


def cmd_list_channels(args):
    if args.dry_run:
        return _dry("conversations.list", {"limit": args.limit, "types": args.types})
    channels = paginate(
        args.token,
        "conversations.list",
        {"limit": args.limit, "types": args.types, "exclude_archived": "true"},
        "channels",
    )
    out = [
        {
            "id": c.get("id"),
            "name": c.get("name"),
            "is_private": c.get("is_private"),
            "is_archived": c.get("is_archived"),
            "num_members": c.get("num_members"),
        }
        for c in channels
    ]
    _emit({"ok": True, "count": len(out), "channels": out})


def cmd_history(args):
    if args.dry_run:
        return _dry("conversations.history", {"channel": args.channel, "limit": args.limit})
    channel_id = resolve_channel(args.token, args.channel)
    payload = api(
        args.token,
        "conversations.history",
        {"channel": channel_id, "limit": args.limit},
    )
    messages = [
        {
            "ts": m.get("ts"),
            "user": m.get("user"),
            "bot_id": m.get("bot_id"),
            "text": m.get("text"),
            "thread_ts": m.get("thread_ts"),
            "reply_count": m.get("reply_count"),
        }
        for m in payload.get("messages") or []
    ]
    _emit({"ok": True, "channel": channel_id, "count": len(messages), "messages": messages})


def cmd_users(args):
    if args.dry_run:
        return _dry("users.list", {"limit": args.limit})
    users = paginate(args.token, "users.list", {"limit": args.limit}, "members")
    out = [
        {
            "id": u.get("id"),
            "name": u.get("name"),
            "real_name": u.get("real_name"),
            "is_bot": u.get("is_bot"),
            "deleted": u.get("deleted"),
        }
        for u in users
    ]
    _emit({"ok": True, "count": len(out), "users": out})


def cmd_upload(args):
    params = {
        "channel": args.channel,
        "file": args.file,
        "filename": args.filename or os.path.basename(os.path.expanduser(args.file)),
        "title": args.title,
        "initial_comment": args.initial_comment,
    }
    if args.dry_run:
        return _dry("files.getUploadURLExternal + files.completeUploadExternal", params)
    file_path = os.path.expanduser(args.file)
    if not os.path.isfile(file_path):
        raise SlackError("file not found: %s" % file_path)
    channel_id = resolve_channel(args.token, args.channel)
    size = os.path.getsize(file_path)
    filename = args.filename or os.path.basename(file_path)

    init = api(
        args.token,
        "files.getUploadURLExternal",
        {"filename": filename, "length": size, "alt_txt": args.title or filename},
    )
    upload_url = init["upload_url"]
    file_id = init["file_id"]

    with open(file_path, "rb") as f:
        file_bytes = f.read()
    _http_request(
        upload_url,
        method="PUT",
        body=file_bytes,
        headers={"Content-Type": "application/octet-stream"},
    )

    complete_params = {
        "files": json.dumps([{"id": file_id, "title": args.title or filename}]),
        "channel_id": channel_id,
    }
    if args.initial_comment:
        complete_params["initial_comment"] = args.initial_comment
    payload = api(args.token, "files.completeUploadExternal", complete_params)
    files = payload.get("files") or []
    first = files[0] if files else {}
    _emit(
        {
            "ok": True,
            "file_id": first.get("id"),
            "title": first.get("title"),
            "permalink": first.get("permalink"),
        }
    )


def cmd_create_channel(args):
    params = {"name": args.name, "is_private": "true" if args.private else "false"}
    if args.dry_run:
        return _dry("conversations.create", params)
    payload = api(args.token, "conversations.create", params)
    c = payload.get("channel") or {}
    _emit(
        {
            "ok": True,
            "id": c.get("id"),
            "name": c.get("name"),
            "is_private": c.get("is_private"),
        }
    )


# --- CLI --------------------------------------------------------------------


def build_parser():
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--token", default=None, help="Bot token (default: $SLACK_BOT_TOKEN)")
    common.add_argument("--dry-run", action="store_true", help="Print the request without sending")

    p = argparse.ArgumentParser(
        prog="slack_api.py",
        description="Slack Web API helper (stdlib only). See --help on subcommands.",
    )
    sub = p.add_subparsers(dest="command", required=True, metavar="<command>")

    sp = sub.add_parser("test", parents=[common], help="Verify token via auth.test")

    sp = sub.add_parser("post", parents=[common], help="Send a message")
    sp.add_argument("--channel", required=True, help="Channel name or ID")
    sp.add_argument("--text", required=True, help="Message text (mrkdwn supported)")
    sp.add_argument("--thread-ts", default=None, help="Parent message ts to reply in a thread")

    sp = sub.add_parser("reply", parents=[common], help="Reply inside a thread")
    sp.add_argument("--channel", required=True, help="Channel name or ID")
    sp.add_argument("--thread-ts", required=True, help="Parent message ts of the thread")
    sp.add_argument("--text", required=True, help="Reply text (mrkdwn supported)")

    sp = sub.add_parser("list-channels", parents=[common], help="List channels (paginated)")
    sp.add_argument("--limit", type=int, default=100, help="Items per page, max 200 (default: 100)")
    sp.add_argument("--types", default="public_channel,private_channel", help="Comma-separated channel types")

    sp = sub.add_parser("history", parents=[common], help="Read recent messages")
    sp.add_argument("--channel", required=True, help="Channel name or ID")
    sp.add_argument("--limit", type=int, default=100, help="Messages to return, max 999 (default: 100)")

    sp = sub.add_parser("users", parents=[common], help="List workspace users (paginated)")
    sp.add_argument("--limit", type=int, default=100, help="Items per page, max 200 (default: 100)")

    sp = sub.add_parser("upload", parents=[common], help="Upload a file to a channel")
    sp.add_argument("--channel", required=True, help="Channel name or ID")
    sp.add_argument("--file", required=True, help="Path to the file to upload")
    sp.add_argument("--filename", default=None, help="Filename shown in Slack (default: basename of --file)")
    sp.add_argument("--title", default=None, help="File title / alt text")
    sp.add_argument("--initial-comment", default=None, help="Optional comment posted with the file")

    sp = sub.add_parser("create-channel", parents=[common], help="Create a channel")
    sp.add_argument("--name", required=True, help="Channel name (lowercase, no spaces)")
    sp.add_argument("--private", action="store_true", help="Create a private channel")
    return p


def main():
    args = build_parser().parse_args()
    if args.token is None:
        args.token = os.environ.get("SLACK_BOT_TOKEN")
    if not args.token and not args.dry_run:
        sys.stderr.write("Failure: missing token. Set SLACK_BOT_TOKEN or pass --token.\n")
        return 1

    handler = {
        "test": cmd_test,
        "post": cmd_post,
        "reply": cmd_reply,
        "list-channels": cmd_list_channels,
        "history": cmd_history,
        "users": cmd_users,
        "upload": cmd_upload,
        "create-channel": cmd_create_channel,
    }[args.command]

    try:
        handler(args)
    except SlackError as e:
        sys.stderr.write("Failure: %s\n" % e)
        return 1
    except urllib.error.URLError as e:
        sys.stderr.write("Failure: network error: %s\n" % e.reason)
        return 1
    except Exception as e:  # noqa: BLE001 - keep output clean for agents
        sys.stderr.write("Failure: %s: %s\n" % (type(e).__name__, e))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
